import {Activity,LayoutDashboard,CalendarDays,Users,Wallet,BarChart3,Settings,Search,Bell,Plus,ChevronLeft,ChevronRight,ArrowUpLeft,Clock,Check,Menu,LogOut,X,Stethoscope,FileText,Heart,ArrowDownLeft,Download,Printer,CheckCircle2,AlertCircle,Shield,Calendar,MoreHorizontal,Leaf,ArrowRight,Globe,RefreshCw,Loader2} from 'lucide-react';
type Row=Record<string,any>;
const statuses:Row={booked:['محجوز','neutral'],confirmed:['مؤكد','teal'],arrived:['في الانتظار','pink'],in_progress:['قيد الكشف','green'],completed:['مكتمل','teal'],cancelled:['ملغي','neutral'],no_show:['لم يحضر','pink']};
