async function api(path:string,data?:any){const r=await fetch('/api/'+path,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json'}:undefined,body:data?JSON.stringify(data):undefined,cache:'no-store'});const b=await r.json();if(!r.ok)throw new Error(errors[b.error]||b.error);return b;}
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Africa/Cairo'}).format(new Date());
const time=(s:string)=>new Intl.DateTimeFormat('ar-EG',{timeZone:'Africa/Cairo',hour:'numeric',minute:'2-digit'}).format(new Date(s));
const money=(n:number)=>new Intl.NumberFormat('ar-EG',{maximumFractionDigits:2}).format((n||0)/100);
const iconList=[LayoutDashboard,CalendarDays,Clock,Users,Stethoscope,Wallet,BarChart3,Settings];
