const arabicDate=new Intl.DateTimeFormat(locale==='ar'?'ar-EG':'en-GB',{weekday:'long',day:'numeric',month:'long',year:'numeric',timeZone:'Africa/Cairo'}).format(new Date(date+'T12:00:00Z'));
function Status({status}:{status:string}){const s=statuses[status]||statuses.booked;return <span className={'status '+s[1]}><span className="status-dot"/>{s[0]}</span>}
function AppointmentTable({compact=false}:{compact?:boolean}){return <div className="table-wrap"><table><thead><tr><th>المريض</th><th>الموعد</th>{!compact&&<th>الطبيب / الخدمة</th>}<th>الحالة</th><th>الإجراء</th></tr></thead><tbody>{filtered.map((ap,i)=><tr key={ap.id}><td><div className="person"><span className={'avatar a'+i%4}>{ap.patient_name.split(' ').slice(0,2).map((s:string)=>s[0]).join('')}</span><div><strong>{ap.patient_name}</strong><small dir="ltr">#{ap.file_number} · {ap.phone}</small></div></div></td><td><strong className="time-cell">{time(ap.starts_at)}</strong><small>{Math.round((+new Date(ap.ends_at)-+new Date(ap.starts_at))/60000)} دقيقة</small></td>{!compact&&<td>{ap.doctor_name}<small>{ap.service_name}</small></td>}<td><Status status={ap.status}/></td><td><div className="row-actions">{canAdmin&&['booked','confirmed'].includes(ap.status)&&<button className="link-btn" onClick={()=>action(()=>mutate('appointments/update',{id:ap.id,status:'arrived'},'تم تسجيل الوصول'))}>تسجيل وصول <ArrowDownLeft size={14}/></button>}{medical&&['arrived','in_progress','completed'].includes(ap.status)&&<button className="link-btn" onClick={()=>start(ap)}>{ap.status==='completed'?'عرض الزيارة':ap.status==='in_progress'?'متابعة الكشف':'بدء الكشف'} <ChevronLeft size={14}/></button>}{canAdmin&&!['in_progress','completed','cancelled','no_show'].includes(ap.status)&&<button className="icon-btn" aria-label="إدارة الموعد" onClick={()=>open('appointmentEdit',ap)}><MoreHorizontal size={19}/></button>}</div></td></tr>)}</tbody></table>{!filtered.length&&<Empty text="لا توجد مواعيد في هذا اليوم" action={canAdmin?()=>open('booking'):undefined}/>}</div>}
