if(!boot)return <main className="login-shell"><section className="login-story"><div className="brand"><span className="brand-mark"><Activity/></span><b>شُريان<span>SHORIAN</span></b></div><span className="eyebrow">مساحة أهدأ. رعاية أفضل.</span><h1>كل تفاصيل عيادتك،<br/>في مكان واحد.</h1><p>من أول موعد إلى آخر زيارة، يوم عمل أكثر سلاسة لفريقك ومرضاك.</p><div className="story-art"><div className="orbit"/><Heart size={90}/><div className="floating-card"><CheckCircle2/> موعدك القادم… أكثر تنظيمًا</div></div><small>إدارة العيادات، بنبض مختلف.</small></section><section className="login-card"><span className="mini-label">أهلًا بعودتك</span><h2>ابدأ يومك مع شُريان</h2><p>سجّل الدخول إلى مساحة عيادتك</p><div className="tabs"><button className={loginMode==='login'?'active':''} onClick={()=>setLoginMode('login')}>تسجيل الدخول</button><button className={loginMode==='register'?'active':''} onClick={()=>setLoginMode('register')}>إنشاء عيادة</button>{demoEnabled&&<button className={loginMode==='demo'?'active':''} onClick={()=>setLoginMode('demo')}>تجربة النظام</button>}</div>{error&&<div className="alert error"><AlertCircle size={18}/>{error}</div>}{loginMode==='demo'?<><div className="demo-notice"><Shield size={22}/><div><strong>بيئة تجريبية ببيانات اصطناعية</strong><p>حفظ فعلي في قاعدة بيانات محلية. لا تُدخل بيانات مرضى حقيقية.</p></div></div><form onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);action(async()=>{await api('auth/demo',Object.fromEntries(f));await refresh();})}}><label>اختر العيادة<select name="clinic"><option value="1">عيادة النور التخصصية</option><option value="2">عيادة الياسمين — عيادة مستقلة</option></select></label><label>الدور<select name="role"><option value="manager">مدير العيادة</option><option value="receptionist">موظف الاستقبال</option><option value="doctor">الطبيب</option><option value="accountant">المحاسب</option><option value="platform">مدير المنصة (دون بيانات المرضى)</option></select></label><button disabled={busy} className="primary full">{busy?<Loader2 className="spin" size={18}/>:<>الدخول إلى العيادة <ArrowLeftIcon/></>}</button></form></>:<form onSubmit={e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.currentTarget));action(async()=>{await api('auth/'+(loginMode==='register'?'register':'login'),f);await refresh()})}}>{loginMode==='register'&&<><label>اسمك<input name="name" required autoComplete="name"/></label><label>اسم العيادة<input name="clinic" required/></label></>}<label>البريد الإلكتروني<input name="email" type="email" required dir="ltr" autoComplete="email"/></label><label>كلمة المرور<input name="password" type="password" minLength={loginMode==='register'?12:1} required dir="ltr" autoComplete={loginMode==='register'?'new-password':'current-password'}/></label><button disabled={busy} className="primary full">{loginMode==='register'?'إنشاء عيادة وتجربة ١٤ يومًا':'تسجيل الدخول'}<ArrowLeftIcon/></button>{loginMode==='register'&&<p className="fine">التحقق من البريد واستعادة كلمة المرور غير مفعّلين في التشغيل المحلي.</p>}</form>}<div className="login-footer"><Shield size={14}/> عضويات مستقلة · صلاحيات في الخادم وقاعدة البيانات</div></section></main>;
